import { scscfIncludeCfg } from '../ims-controller';
import {
  withScscfAuthAlg,
  SCSCF_DEFAULT_AUTH_ALG,
  SCSCF_TEST_AUTH_ALG,
} from '../volte-validation-controller';
import { dispatcherEntryLine, formatPstnDispatcherEntry } from '../pstn-controller';
import * as fs from 'fs';
import * as path from 'path';

/**
 * Two files under /etc/kamailio_scscf/ are written by a module that does not
 * own them, and each has already broken once in production.
 *
 * scscf.cfg is generated by ims-controller.ts. Three validation modules
 * (VoLTE, VoWiFi, QCI) reach into it to flip the registration auth algorithm
 * to MD5 for the duration of a test and back afterwards -- a regex against
 * another module's output, with no test. The failure mode is quiet: String
 * .replace returns its input untouched on a miss, so a format change in IMS
 * would mean the file is written back identical, S-CSCF is restarted anyway
 * (dropping every registered UE, since usrloc is memory-only), and the test
 * proceeds against whatever mode was already live while reporting success.
 *
 * dispatcher.list is written by BOTH ims-controller.ts and pstn-controller.ts.
 * Confirmed live 2026-09-18: an IMS Configure used to deploy the placeholder
 * template unconditionally, silently wiping PSTN's entry and breaking every
 * PSTN-routed call the next time an operator re-ran an unrelated IMS
 * Configure. The fix was for IMS to rebuild PSTN's line through PSTN's own
 * exported formatter -- correct, and until now untested, so drift between the
 * two was invisible.
 */

const SRC = path.resolve(__dirname, '..');
const read = (f: string): string => fs.readFileSync(path.join(SRC, f), 'utf-8');

const PARAMS = {
  imsDomain: 'ims.mnc001.mcc001.3gppnetwork.org',
  mcc: '001',
  mnc: '01',
  scscfIp: '127.0.1.2',
  scscfPort: 6060,
  icscfIp: '127.0.1.1',
  hssIp: '127.0.1.3',
};

describe('scscf.cfg: the auth-algorithm define IMS emits and validation rewrites', () => {
  // scscfIncludeCfg accepts PARAMS as-is: the fields above are the ones this
  // define depends on, and the generator's remaining params are optional.
  const generated = scscfIncludeCfg(PARAMS);

  it('emits the define exactly once', () => {
    const hits = generated.match(/#!define REG_AUTH_DEFAULT_ALG "[^"]*"/g) ?? [];
    expect(hits.length).toBe(1);
  });

  it('defaults to the value the revert path writes back', () => {
    // If these drift, "always reverted" restores a value IMS never produces,
    // and it stays that way until the next full Configure.
    expect(generated).toContain(`#!define REG_AUTH_DEFAULT_ALG "${SCSCF_DEFAULT_AUTH_ALG}"`);
  });

  it('is actually matched by the rewrite — the no-op is the hazard', () => {
    // This is the assertion that earns its place: a silent miss restarts
    // S-CSCF for nothing and runs the test in the wrong mode.
    const { changed, cfg } = withScscfAuthAlg(generated, true);
    expect(changed).toBe(true);
    expect(cfg).toContain(`#!define REG_AUTH_DEFAULT_ALG "${SCSCF_TEST_AUTH_ALG}"`);
    expect(cfg).not.toContain(`"${SCSCF_DEFAULT_AUTH_ALG}"`);
  });

  it('round-trips to byte-identical output', () => {
    // Enabling then reverting has to leave the file exactly as IMS generated
    // it, or every test run leaves a residue behind.
    const { cfg: toTest } = withScscfAuthAlg(generated, true);
    const { cfg: reverted } = withScscfAuthAlg(toTest, false);
    expect(reverted).toBe(generated);
  });

  it('reports a miss rather than silently changing nothing', () => {
    const { changed, cfg } = withScscfAuthAlg('#!define SOMETHING_ELSE "x"\n', true);
    expect(changed).toBe(false);
    expect(cfg).toBe('#!define SOMETHING_ELSE "x"\n');
  });

  it('touches only that one define', () => {
    const { cfg } = withScscfAuthAlg(generated, true);
    const diff = cfg.split('\n').filter((l, i) => l !== generated.split('\n')[i]);
    expect(diff.length).toBe(1);
    expect(diff[0]).toContain('REG_AUTH_DEFAULT_ALG');
  });

  it('refuses to restart S-CSCF when the define is missing', () => {
    // The restart is what drops every registration, so it must not happen on
    // a file this code could not actually edit.
    const src = read('volte-validation-controller.ts');
    const fn = src.slice(src.indexOf('export async function setScscfTestAuthMode'));
    const body = fn.slice(0, fn.indexOf('\n}\n'));
    expect(body).toMatch(/if \(!changed\)/);
    expect(body.indexOf('throw new Error')).toBeLessThan(body.indexOf('systemctl'));
  });
});

describe('dispatcher.list: one syntax, two writers', () => {
  it('builds the entry from a single definition', () => {
    expect(dispatcherEntryLine('127.0.1.4', 5060)).toBe('1 sip:127.0.1.4:5060\n');
  });

  it('ends with a newline, since kamailio reads the file line-wise', () => {
    expect(dispatcherEntryLine('10.0.0.1', 5080).endsWith('\n')).toBe(true);
  });

  it('routes both writers through that definition, not their own literal', () => {
    // The two used to be separate template literals that merely agreed. A
    // source check is the only way to assert the private writer's path.
    const src = read('pstn-controller.ts');
    expect(src).toContain('dispatcherEntryLine(asteriskIp, ASTERISK_PORT)');
    expect(src).toContain('dispatcherEntryLine(bind.ip, bind.port)');
    // The syntax itself appears exactly once in the file: inside
    // dispatcherEntryLine. A second occurrence means someone reintroduced a
    // parallel copy, which is the state this consolidation removed.
    expect((src.match(/`1 sip:\$\{/g) ?? []).length).toBe(1);
  });

  it('gives IMS null when PSTN was never configured', () => {
    // Null is what makes IMS fall back to the placeholder template instead of
    // writing a half-formed entry for a module that does not exist yet.
    const out = formatPstnDispatcherEntry();
    expect(out === null || /^1 sip:\S+:\d+\n$/.test(out)).toBe(true);
  });

  it('makes IMS preserve PSTN\'s entry and only fall back when there is none', () => {
    const ims = read('ims-controller.ts');
    const at = ims.indexOf('const pstnDispatcherEntry = formatPstnDispatcherEntry();');
    expect(at).toBeGreaterThan(0);
    const block = ims.slice(at, at + 500);
    // The write must be guarded by the entry existing, with the template as
    // the else branch -- not the other way round, and not unconditional.
    expect(block).toMatch(/if \(pstnDispatcherEntry\) \{/);
    expect(block.indexOf('dispatcher.list')).toBeLessThan(block.indexOf('deployImsTemplate'));
  });

  it('writes a comment, not a bare address, when PSTN is disabled', () => {
    // A disabled gateway must not leave anything kamailio could parse as a
    // live destination.
    const src = read('pstn-controller.ts');
    const fn = src.slice(src.indexOf('async function clearDispatcherEntry'));
    const written = /HOST_DISPATCHER_LIST, '([^']*)'/.exec(fn)?.[1];
    expect(written).toBeDefined();
    expect(written!.startsWith('#')).toBe(true);
    expect(written).not.toMatch(/sip:/);
  });

  it('agrees with the validation module on which directory these live in', () => {
    // Three modules name this path independently; if one moves, the others
    // write to a file kamailio is not reading.
    for (const f of ['pstn-controller.ts', 'volte-validation-controller.ts', 'ims-controller.ts']) {
      expect(read(f)).toContain('/etc/kamailio_scscf');
    }
  });
});
